1	//! Chat input: a multi-line, Piton-highlighted editor on the left and a send
2	//! button on the right, in the body of the Code, chain, and Spec tabs. Enter adds a
3	//! line; Ctrl/Cmd+Enter sends, or queues the prompt while the harness works.
4	//! Tab and Shift+Tab cycle the tabs and Esc takes focus out of the input.
5	
6	use std::rc::Rc;
7	use std::sync::Arc;
8	
9	use gpui_kit::Focusable as _;
10	use gpui_kit::assets::IconName;
11	use gpui_kit::component::button::{Button, ButtonVariants};
12	use gpui_kit::component::input::{
13	    CompletionProvider, Editor, EditorState, Enter, Escape, IndentInline, InputEvent, MoveDown,
14	    MoveUp, OutdentInline, Rope,
15	};
16	use gpui_kit::component::tab::{Tab, TabBar};
17	use gpui_kit::component::{ActiveTheme, Disableable, FocusableExt as _};
18	use gpui_kit::prelude::FluentBuilder as _;
19	use gpui_kit::*;
20	use lsp_types::{CompletionContext, CompletionResponse};
21	
22	use crate::completion_menu::CompletionMenu;
23	use crate::harness_mentions;
24	use crate::main_window::FocusChat;
25	use crate::piton_lsp::PitonSession;
26	use crate::piton_syntax;
27	use crate::project_directory::ProjectDirectory;
28	use crate::project_lsp::ProjectLsp;
29	
30	/// The input grows with its text up to this many rows, then scrolls.
31	const MAX_ROWS: usize = 12;
32	
33	/// Room the editor keeps free at the right of each line when soft wrapping.
34	const WRAP_RIGHT_MARGIN: Pixels = px(10.);
35	
36	#[cfg(target_os = "macos")]
37	const SEND_SHORTCUT: &str = "⌘Enter";
38	#[cfg(not(target_os = "macos"))]
39	const SEND_SHORTCUT: &str = "Ctrl+Enter";
40	
41	/// The tabs the input sits in, in the order Tab cycles them.
42	const TABS: [SendMode; 3] = [SendMode::Code, SendMode::Both, SendMode::Spec];
43	
44	/// The side of the square chain tab, half the height of the tabs.
45	const BOTH_TAB_SIZE: Pixels = px(16.);
46	
47	/// Index of the chain tab in `TABS`.
48	const BOTH_TAB: usize = 1;
49	
50	/// The gap between Code and Spec while the chain is inactive: the chain, with
51	/// room either side so it overlaps neither tab.
52	const CHAIN_GAP: Pixels = px(16. + 6. * 2.);
53	
54	/// How the tabs slide toward and away from the chain: critically damped, so
55	/// they meet without bouncing past the seam.
56	const CHAIN_SPRING: SpringConfig = SpringConfig::new(400., 40., 1.);
57	
58	/// How strongly the selected tabs and their body are tinted: red for Code,
59	/// blue for Spec, and purple for both.
60	const TINT_OPACITY: f32 = 0.1;
61	
62	/// The tint at `position` between the tabs: red at Code (0), blue at Spec
63	/// (2), and purple for both (1), where they meet.
64	fn tint(red: Hsla, blue: Hsla, position: f32) -> Hsla {
65	    let t = (position / 2.).clamp(0., 1.);
66	    // The shorter way round the hue circle, which from red to blue passes
67	    // through purple rather than green.
68	    let hue_step = (blue.h - red.h + 0.5).rem_euclid(1.) - 0.5;
69	    Hsla {
70	        h: (red.h + hue_step * t).rem_euclid(1.),
71	        s: red.s + (blue.s - red.s) * t,
72	        l: red.l + (blue.l - red.l) * t,
73	        a: TINT_OPACITY,
74	    }
75	}
76	
77	/// What a prompt is sent to work on: the selected tab.
78	#[derive(Clone, Copy, Debug, PartialEq)]
79	pub enum SendMode {
80	    Code,
81	    /// The code and the spec together.
82	    Both,
83	    Spec,
84	}
85	
86	impl SendMode {
87	    fn label(self) -> &'static str {
88	        match self {
89	            SendMode::Code => "Code",
90	            SendMode::Both => "Code and Spec",
91	            SendMode::Spec => "Spec",
92	        }
93	    }
94	
95	    fn id(self) -> &'static str {
96	        match self {
97	            SendMode::Code => "code-tab",
98	            SendMode::Both => "both-tab",
99	            SendMode::Spec => "spec-tab",
100	        }
101	    }
102	}
103	
104	/// Emitted with the input's text, and the mode it is sent in, when the user
105	/// sends it.
106	pub struct Submit {
107	    pub text: String,
108	    pub mode: SendMode,
109	}
110	
111	pub struct ChatInput {
112	    editor: Entity<EditorState>,
113	    completion: Entity<CompletionMenu>,
114	    /// The tab bar and its body, which Esc moves focus to: out of the input,
115	    /// but not onto nothing, where the window would hand it straight back.
116	    focus_handle: FocusHandle,
117	    /// Index into `TABS`.
118	    selected_tab: usize,
119	    lsp: Option<Arc<PitonSession>>,
120	    busy: bool,
121	    /// Width the editor's text was last laid out in, which decides where long
122	    /// lines soft wrap.
123	    text_width: Option<Pixels>,
124	    /// What the editor adds around its rows (padding and border) as last
125	    /// laid out, rounded to device pixels.
126	    chrome: Option<Pixels>,
127	    _subscriptions: Vec<Subscription>,
128	}
129	
130	impl EventEmitter<Submit> for ChatInput {}
131	
132	impl ChatInput {
133	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
134	        let editor = cx.new(|cx| {
135	            EditorState::new(window, cx)
136	                .language(piton_syntax::LANGUAGE_NAME)
137	                .line_number(false)
138	                .folding(false)
139	                .soft_wrap(true)
140	                // No empty rows below the last line: the input is sized to its
141	                // text, so any extra would be blank space, and it would leave
142	                // room for the editor to stay scrolled past the first line
143	                // after Enter grows the input.
144	                .scroll_beyond_last_line(Some(0))
145	                .placeholder(format!(
146	                    "Write a prompt… (/ for skills and commands, @ for agents, {SEND_SHORTCUT} to send)"
147	                ))
148	        });
149	        // Typing goes straight into the input, without clicking it first.
150	        editor.read(cx).focus_handle(cx).focus(window, cx);
151	        let completion = cx.new(|cx| CompletionMenu::new(editor.clone(), window, cx));
152	
153	        let subscriptions = vec![
154	            cx.subscribe_in(&editor, window, |this, editor, event: &InputEvent, window, cx| {
155	                if matches!(event, InputEvent::Change) {
156	                    // An edit may be an accepted completion, whose import the
157	                    // hidden anchor then takes on.
158	                    if let Some(lsp) = &this.lsp {
159	                        lsp.note_edit(&editor.read(cx).value());
160	                    }
161	                    this.completion
162	                        .update(cx, |menu, cx| menu.on_edit(window, cx));
163	                }
164	                // Re-render on every edit so the input can grow to fit its text.
165	                cx.notify();
166	            }),
167	            cx.observe_global_in::<ProjectLsp>(window, |this, _, cx| this.connect_lsp(cx)),
168	        ];
169	
170	        let mut this = Self {
171	            editor,
172	            completion,
173	            focus_handle: cx.focus_handle(),
174	            selected_tab: 0,
175	            lsp: None,
176	            busy: false,
177	            text_width: None,
178	            chrome: None,
179	            _subscriptions: subscriptions,
180	        };
181	        this.connect_lsp(cx);
182	        this
183	    }
184	
185	    /// The project's `piton lsp` session, once it is running.
186	    pub fn lsp(&self) -> Option<Arc<PitonSession>> {
187	        self.lsp.clone()
188	    }
189	
190	    /// Moves keyboard focus into the input.
191	    pub fn focus(&mut self, window: &mut Window, cx: &mut Context<Self>) {
192	        self.editor.read(cx).focus_handle(cx).focus(window, cx);
193	    }
194	
195	    /// Inserts a harness mention at the cursor, after a space when the cursor
196	    /// follows other text, then moves focus into the input.
197	    pub fn insert_mention(&mut self, mention: &str, window: &mut Window, cx: &mut Context<Self>) {
198	        self.editor.update(cx, |editor, cx| {
199	            let value = editor.value();
200	            let follows_text = value
201	                .get(..editor.cursor())
202	                .and_then(|before| before.chars().next_back())
203	                .is_some_and(|c| !c.is_whitespace());
204	            let text = if follows_text {
205	                format!(" {mention}")
206	            } else {
207	                mention.to_string()
208	            };
209	            editor.insert(text, window, cx);
210	        });
211	        self.focus(window, cx);
212	    }
213	
214	    #[cfg(test)]
215	    pub fn value(&self, cx: &App) -> SharedString {
216	        self.editor.read(cx).value()
217	    }
218	
219	    #[cfg(test)]
220	    pub fn is_focused(&self, window: &Window, cx: &App) -> bool {
221	        self.editor.read(cx).focus_handle(cx).is_focused(window)
222	    }
223	
224	    /// Marks the harness as working; sending then queues the prompt.
225	    pub fn set_busy(&mut self, busy: bool, cx: &mut Context<Self>) {
226	        self.busy = busy;
227	        cx.notify();
228	    }
229	
230	    /// Points completions at the project's `piton lsp`, once it is running.
231	    /// Harness mentions complete without it.
232	    fn connect_lsp(&mut self, cx: &mut Context<Self>) {
233	        let client = ProjectLsp::get(cx);
234	        let connected = self.lsp.as_ref().map(|lsp| Arc::as_ptr(lsp.client()));
235	        if client.as_ref().map(Arc::as_ptr) == connected {
236	            return;
237	        }
238	        self.lsp = client.map(|client| Arc::new(PitonSession::new(client)));
239	        self.set_completions(self.lsp.clone(), cx);
240	    }
241	
242	    fn set_completions(&mut self, lsp: Option<Arc<PitonSession>>, cx: &mut Context<Self>) {
243	        let completions = Rc::new(PromptCompletions { lsp });
244	        self.completion
245	            .update(cx, |menu, cx| menu.set_provider(completions, cx));
246	    }
247	
248	    fn submit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
249	        let text = self.editor.read(cx).value().to_string();
250	        if text.is_empty() {
251	            return;
252	        }
253	        self.editor
254	            .update(cx, |editor, cx| editor.set_value("", window, cx));
255	        cx.emit(Submit {
256	            text,
257	            mode: TABS[self.selected_tab],
258	        });
259	    }
260	
261	    /// Selects a clicked tab and puts focus back in the input.
262	    fn select_tab(&mut self, ix: usize, window: &mut Window, cx: &mut Context<Self>) {
263	        self.selected_tab = ix;
264	        self.focus(window, cx);
265	        cx.notify();
266	    }
267	
268	    /// Moves `step` tabs along, wrapping around. An open completion menu
269	    /// keeps its own Tab and Shift+Tab.
270	    fn cycle_tab(&mut self, step: isize, cx: &mut Context<Self>) {
271	        if self.completion.read(cx).is_open() {
272	            return;
273	        }
274	        cx.stop_propagation();
275	        let count = TABS.len() as isize;
276	        self.selected_tab = (self.selected_tab as isize + step).rem_euclid(count) as usize;
277	        cx.notify();
278	    }
279	
280	    /// Esc closes an open completion menu, and otherwise takes focus out of
281	    /// the input.
282	    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
283	        if self.completion.read(cx).is_open() {
284	            self.completion.update(cx, |menu, cx| menu.hide(cx));
285	        } else {
286	            self.focus_handle.focus(window, cx);
287	        }
288	    }
289	
290	    /// The rows `text` takes in the editor: one per line, plus one for every
291	    /// soft wrap, wrapped the way the editor wraps it.
292	    fn visual_rows(&self, text: &str, window: &Window, cx: &App) -> usize {
293	        let Some(wrap_width) = self.text_width.map(|width| width - WRAP_RIGHT_MARGIN) else {
294	            return text.split('\n').count();
295	        };
296	        let theme = cx.theme();
297	        let mut wrapper = window
298	            .text_system()
299	            .line_wrapper(font(theme.mono_font_family.clone()), theme.mono_font_size);
300	        text.split('\n')
301	            .map(|line| {
302	                1 + wrapper
303	                    .wrap_line(&[LineFragment::text(line)], wrap_width)
304	                    .count()
305	            })
306	            .sum()
307	    }
308	}
309	
310	impl Render for ChatInput {
311	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
312	        let text = self.editor.read(cx).value();
313	        let rows = self.visual_rows(&text, window, cx).clamp(1, MAX_ROWS);
314	        // Fit the text with the editor's own metrics: its laid-out line height
315	        // plus the padding and border around its rows. Until the editor has
316	        // painted, the border is estimated at a device pixel or more per side.
317	        let line_height = self
318	            .editor
319	            .read(cx)
320	            .line_height()
321	            .unwrap_or_else(|| window.line_height());
322	        let chrome = self.chrome.unwrap_or_else(|| {
323	            gpui_kit::component::Size::Medium.input_py() * 2.
324	                + ceil_to_device_pixel(px(1.), window) * 2.
325	        });
326	        let height = ceil_to_device_pixel(line_height * rows as f32 + chrome, window);
327	        let one_row = ceil_to_device_pixel(line_height + chrome, window);
328	        let empty = text.is_empty();
329	
330	        // Once the editor has painted, check how it was laid out: the width
331	        // its text wrapped in (a resized window wraps long lines differently)
332	        // and the padding and border around its rows. When either changed,
333	        // the input re-fits.
334	        let this = cx.entity().downgrade();
335	        let editor = self.editor.clone();
336	        let track_layout = canvas(
337	            |_, _, _| {},
338	            move |bounds, _, _, cx| {
339	                let Some(text_bounds) = editor.read(cx).text_bounds() else {
340	                    return;
341	                };
342	                let width = text_bounds.size.width;
343	                let chrome = bounds.size.height - text_bounds.size.height;
344	                this.update(cx, |this, cx| {
345	                    let chrome_changed = this
346	                        .chrome
347	                        .is_none_or(|old| (old - chrome).abs() > px(0.01));
348	                    if this.text_width != Some(width) || chrome_changed {
349	                        this.text_width = Some(width);
350	                        if chrome_changed {
351	                            this.chrome = Some(chrome);
352	                        }
353	                        cx.notify();
354	                    }
355	                })
356	                .ok();
357	            },
358	        )
359	        .absolute()
360	        .size_full();
361	
362	        // Code and Spec are full tabs, each its own bar, with a gap between
363	        // them where the chain sits: broken and dimmed until selected, then
364	        // joined. Selecting it selects both tabs, which slide toward the chain
365	        // until they meet beneath it, so they read as one locked tab. The chain
366	        // itself never moves; only the tabs slide.
367	        let selected = self.selected_tab;
368	        let unified = selected == BOTH_TAB;
369	        // How far each tab has slid toward the chain: none while apart, half
370	        // the gap once they meet.
371	        let slide = SpringAnimation::new(CHAIN_SPRING).to(if unified {
372	            CHAIN_GAP * 0.5
373	        } else {
374	            px(0.)
375	        });
376	        // The tint slides between the tabs the same way, so going from Code
377	        // to Spec passes through purple. Its position is the selected tab's
378	        // index: 0 for Code, 1 for both, 2 for Spec.
379	        let tint_slide = SpringAnimation::new(CHAIN_SPRING).to(selected as f32);
380	        let (red, blue) = (cx.theme().red, cx.theme().blue);
381	        // A tint laid over a tab, as wide as the tab itself (an invisible copy
382	        // of it) rather than its bar, fading out as the tab is deselected.
383	        let tab_tint = |ix: usize| {
384	            let tint_slide = tint_slide.clone();
385	            div()
386	                .absolute()
387	                .top_0()
388	                .bottom_0()
389	                .left_0()
390	                .flex()
391	                .child(
392	                    TabBar::new(("tint-width", ix))
393	                        .selected_index(0)
394	                        .child(Tab::new().label(TABS[ix].label()).px_2())
395	                        .invisible(),
396	                )
397	                .with_spring(("tab-tint", ix), tint_slide, move |this, position| {
398	                    // Full while the tab is selected, alone or with the other,
399	                    // and gone once the other is selected alone.
400	                    let shown = (2. - (position - ix as f32).abs()).clamp(0., 1.);
401	                    let color = tint(red, blue, position);
402	                    this.bg(Hsla {
403	                        a: color.a * shown,
404	                        ..color
405	                    })
406	                })
407	        };
408	        let chat_input = cx.entity().downgrade();
409	        let full_tab = |ix: usize| {
410	            let chat_input = chat_input.clone();
411	            let bar = TabBar::new(TABS[ix].id())
412	                .on_click(move |_, window, cx| {
413	                    chat_input
414	                        .update(cx, |this, cx| this.select_tab(ix, window, cx))
415	                        .ok();
416	                })
417	                .child(Tab::new().label(TABS[ix].label()).px_2());
418	            if selected == ix || unified {
419	                bar.selected_index(0)
420	            } else {
421	                bar
422	            }
423	        };
424	        let code = div()
425	            .relative()
426	            .child(full_tab(0))
427	            .child(tab_tint(0))
428	            .with_spring("code-slide", slide.clone(), |this, slide| this.left(slide));
429	        // Spec stretches to the right edge, so it slides by pulling its left
430	        // edge in rather than moving as a whole.
431	        let spec = div()
432	            .relative()
433	            .flex_1()
434	            .ml(CHAIN_GAP)
435	            .child(full_tab(2).w_full())
436	            .child(tab_tint(2))
437	            .with_spring("spec-slide", slide.clone(), |this, slide| {
438	                this.ml(CHAIN_GAP - slide)
439	            });
440	        let both = Button::new("both")
441	            .outline()
442	            .icon(if unified {
443	                IconName::Link
444	            } else {
445	                IconName::Unlink
446	            })
447	            .tooltip(SendMode::Both.label())
448	            .size(BOTH_TAB_SIZE)
449	            .focus_ring(false)
450	            .tab_stop(false)
451	            .on_click(cx.listener(|this, _, window, cx| this.select_tab(BOTH_TAB, window, cx)));
452	        let both = if unified { both.primary() } else { both };
453	        // The selected tabs' facing borders, covered once the tabs meet, in
454	        // their purple.
455	        let meet = CHAIN_GAP * 0.5 - px(0.5);
456	        let seam_cover = cx.theme().tab_active.blend(tint(red, blue, BOTH_TAB as f32));
457	        let cover = div()
458	            .absolute()
459	            .top_0()
460	            .bottom_0()
461	            .left(px(-1.))
462	            .w(px(2.))
463	            .with_spring("seam-cover", slide, move |this, slide| {
464	                if slide >= meet {
465	                    this.bg(seam_cover)
466	                } else {
467	                    this
468	                }
469	            });
470	        // An invisible copy of the Code tab bar and half the gap put the
471	        // chain's place, whatever width Code's label takes.
472	        let seam = div()
473	            .absolute()
474	            .left_0()
475	            .top_0()
476	            .bottom_0()
477	            .flex()
478	            .child(
479	                TabBar::new("code-tab-width")
480	                    .child(Tab::new().label(SendMode::Code.label()).px_2())
481	                    .invisible(),
482	            )
483	            .child(div().w(CHAIN_GAP * 0.5))
484	            .child(
485	                div()
486	                    .relative()
487	                    .w_0()
488	                    .flex()
489	                    .items_center()
490	                    .child(cover)
491	                    .child(
492	                        div().relative().w_0().h(BOTH_TAB_SIZE).child(
493	                            gpui_kit::TestSupportExt::test_support(
494	                                div()
495	                                    .id(SendMode::Both.id())
496	                                    .absolute()
497	                                    .top_0()
498	                                    .left(BOTH_TAB_SIZE * -0.5)
499	                                    .rounded(cx.theme().radius)
500	                                    .when(unified, |this| this.bg(cx.theme().background))
501	                                    .opacity(if unified { 1. } else { 0.5 })
502	                                    .child(both),
503	                            ),
504	                        ),
505	                    ),
506	            );
507	        let tabs = gpui_kit::TestSupportExt::test_support(
508	            div()
509	                .id("chat-tabs")
510	                .relative()
511	                .flex()
512	                .items_center()
513	                .bg(cx.theme().tab_bar)
514	                .child(
515	                    div()
516	                        .absolute()
517	                        .left_0()
518	                        .bottom_0()
519	                        .size_full()
520	                        .border_b_1()
521	                        .border_color(cx.theme().border),
522	                )
523	                .child(code)
524	                .child(spec)
525	                .child(seam),
526	        );
527	
528	        let body = div()
529	            .flex()
530	            .flex_row()
531	            .items_end()
532	            .gap_2()
533	            .p_3()
534	            .with_spring("body-tint", tint_slide, move |this, position| {
535	                this.bg(tint(red, blue, position))
536	            });
537	
538	        div()
539	            .track_focus(&self.focus_handle)
540	            .flex()
541	            .flex_col()
542	            .border_t_1()
543	            .border_color(cx.theme().border)
544	            // Tab and Shift+Tab cycle the tabs rather than indenting, and the
545	            // input keeps focus.
546	            .capture_action(cx.listener(|this, _: &IndentInline, _, cx| this.cycle_tab(1, cx)))
547	            .capture_action(cx.listener(|this, _: &OutdentInline, _, cx| this.cycle_tab(-1, cx)))
548	            // Esc arrives as the window's FocusChat, which matches ahead of the
549	            // editor's own binding, or as the editor's Escape once it has
550	            // nothing to cancel. Handled here, neither reaches the window,
551	            // which would focus the input again.
552	            .on_action(cx.listener(|this, _: &FocusChat, window, cx| this.escape(window, cx)))
553	            .on_action(cx.listener(|this, _: &Escape, window, cx| this.escape(window, cx)))
554	            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
555	                // Catch Ctrl/Cmd+Enter before the editor turns it into a newline.
556	                if action.secondary {
557	                    cx.stop_propagation();
558	                    this.submit(window, cx);
559	                } else if this.completion.read(cx).is_open() {
560	                    // Enter accepts the completion instead of adding a line.
561	                    cx.stop_propagation();
562	                    this.completion
563	                        .update(cx, |menu, cx| menu.accept_selected(window, cx));
564	                }
565	            }))
566	            // Up and Down move through an open completion menu instead of
567	            // the text.
568	            .capture_action(cx.listener(|this, _: &MoveUp, window, cx| {
569	                if this.completion.read(cx).is_open() {
570	                    cx.stop_propagation();
571	                    this.completion
572	                        .update(cx, |menu, cx| menu.select_next(-1, window, cx));
573	                }
574	            }))
575	            .capture_action(cx.listener(|this, _: &MoveDown, window, cx| {
576	                if this.completion.read(cx).is_open() {
577	                    cx.stop_propagation();
578	                    this.completion
579	                        .update(cx, |menu, cx| menu.select_next(1, window, cx));
580	                }
581	            }))
582	            .child(tabs)
583	            .child(
