613	/// Completions for the chat input: harness mentions after `/` or `@`, and
614	/// Piton from `piton lsp`, when it is running, everywhere else.
615	struct PromptCompletions {
616	    lsp: Option<Arc<PitonSession>>,
617	}
618	
619	impl CompletionProvider for PromptCompletions {
620	    fn completions(
621	        &self,
622	        text: &Rope,
623	        offset: usize,
624	        _: CompletionContext,
625	        _: &mut Window,
626	        cx: &mut App,
627	    ) -> Task<Result<CompletionResponse>> {
628	        let lsp = self.lsp.clone();
629	        let prompt = text.to_string();
630	        let project_dir = ProjectDirectory::get(cx);
631	        cx.background_spawn(async move {
632	            if harness_mentions::mention_at(&prompt, offset).is_some() {
633	                let invocables = harness_mentions::discover(project_dir.as_deref());
634	                let items = harness_mentions::complete(&prompt, offset, &invocables);
635	                return Ok(CompletionResponse::Array(items.unwrap_or_default()));
636	            }
637	            // A slash or hyphen only triggers completion inside a mention.
638	            let typed = prompt
639	                .get(..offset)
640	                .and_then(|before| before.chars().next_back());
641	            match lsp {
642	                Some(lsp) if !matches!(typed, Some('/' | '-')) => lsp.complete(&prompt, offset),
643	                _ => Ok(CompletionResponse::Array(Vec::new())),
644	            }
645	        })
646	    }
647	
648	    fn is_completion_trigger(&self, _: usize, new_text: &str, _: &mut App) -> bool {
649	        new_text.chars().last().is_some_and(|c| {
650	            c.is_alphanumeric() || matches!(c, '{' | '.' | '$' | '@' | ':' | '_' | '/' | '-')
651	        })
652	    }
653	}
