911	    /// The Code tab, the chain, and the Spec tab, as last laid out.
912	    fn chain_layout(window: &mut Window, cx: &mut gpui_kit::App) -> (Bounds, Bounds, Bounds) {
913	        window.render_frame(cx);
914	        (
915	            window.within("code-tab").find(0usize).bounds(),
916	            window.find("both-tab").bounds(),
917	            window.within("spec-tab").find(0usize).bounds(),
918	        )
