921	    /// Draws frames until the gap between Code and Spec is `gap`.
922	    fn settle_chain(
923	        handle: gpui_kit::AnyWindowHandle,
924	        gap: gpui_kit::Pixels,
925	        cx: &mut TestAppContext,
926	    ) -> (Bounds, Bounds, Bounds) {
927	        let start = std::time::Instant::now();
928	        loop {
929	            let layout = cx
930	                .update_window(handle, |_, window, cx| chain_layout(window, cx))
931	                .unwrap();
932	            let (code, _, spec) = layout;
933	            if (spec.left() - code.right() - gap).abs() <= super::px(0.5) {
934	                return layout;
935	            }
936	            assert!(
937	                start.elapsed() < TIMEOUT,
938	                "the tabs did not settle {gap:?} apart: Code {code:?}, Spec {spec:?}"
939	            );
940	            std::thread::sleep(Duration::from_millis(16));
941	        }
942	    }
943	
944	    /// The chain is a square half the height of the tabs, centred on them.
945	    /// Inactive, it sits in the gap between Code and Spec, overlapping neither.
946	    /// Active, the tabs slide in until they meet beneath it, and it overlaps
947	    /// both, centred on the seam. The chain stays put throughout.
948	    #[gpui_kit::test]
949	    async fn chain_joins_the_tabs_beneath_it(cx: &mut TestAppContext) {
950	        cx.update(|cx| {
951	            gpui_kit::init(cx);
952	            piton_syntax::init();
953	            ProjectDirectory::init(cx);
954	        });
955	        let window = cx.add_window(|window, cx| {
956	            let input = cx.new(|cx| ChatInput::new(window, cx));
957	            Root::new(input, window, cx)
958	        });
959	        let handle = window.into();
960	        cx.wait_for(handle, TIMEOUT, |window, _| {
961	            window.try_find("prompt-editor").is_some()
962	        })
963	        .await;
964	
965	        let (code, chain, spec) = settle_chain(handle, super::CHAIN_GAP, cx);
966	        assert_eq!(
967	            chain.size.width, chain.size.height,
968	            "chain {chain:?} is not square"
969	        );
970	        assert!(
971	            (chain.size.height - code.size.height * 0.5).abs() <= super::px(0.5),
972	            "chain {chain:?} is not half the height of Code {code:?}"
973	        );
974	        assert!(
975	            (chain.center().y - code.center().y).abs() <= super::px(0.5),
976	            "chain {chain:?} is not centred on Code {code:?}"
977	        );
978	        assert!(
979	            code.right() <= chain.left() && chain.right() <= spec.left(),
980	            "inactive chain {chain:?} overlaps Code {code:?} or Spec {spec:?}"
981	        );
982	        assert!(
983	            (chain.center().x - (code.right() + spec.left()) * 0.5).abs() <= super::px(0.5),
984	            "inactive chain {chain:?} is not centred in the gap"
985	        );
986	        let resting = chain;
987	
988	        // Tab moves to the chain; the tabs slide rather than jump together.
989	        cx.update_window(handle, |_, window, cx| window.press("tab", cx))
990	            .unwrap();
991	        let (code, _, spec) = cx
992	            .update_window(handle, |_, window, cx| chain_layout(window, cx))
993	            .unwrap();
994	        assert!(
995	            spec.left() - code.right() > super::px(1.),
996	            "the tabs met without sliding: Code {code:?}, Spec {spec:?}"
997	        );
998	
999	        let (code, chain, spec) = settle_chain(handle, super::px(0.), cx);
1000	        assert_eq!(chain, resting, "the chain moved when activated");
1001	        assert!(
1002	            chain.left() < code.right() && spec.left() < chain.right(),
1003	            "active chain {chain:?} does not overlap Code {code:?} and Spec {spec:?}"
1004	        );
1005	        assert!(
1006	            (chain.center().x - code.right()).abs() <= super::px(0.5),
1007	            "active chain {chain:?} is not centred on the seam at {:?}",
1008	            code.right()
1009	        );
1010	
1011	        // Back to Code: the tabs slide apart again, around the same chain.
1012	        cx.update_window(handle, |_, window, cx| window.press("shift-tab", cx))
1013	            .unwrap();
1014	        let (_, chain, _) = settle_chain(handle, super::CHAIN_GAP, cx);
1015	        assert_eq!(chain, resting, "the chain moved when deactivated");
1016	    }
