1	//! The hidden anchor. Prompts are typed as plain text, but behind the scenes
2	//! they are the `userPrompt` of a randomly-named Piton anchor whose imports
3	//! `piton lsp` adds automatically (see [`crate::piton_lsp`]), so they are never
4	//! written or seen. Each sent prompt is saved as a `.pi` file in the project's
5	//! prompt history and compiled; the compiled `userPrompt` is what the harness
6	//! receives.
7	
8	use std::collections::{BTreeMap, BTreeSet};
9	use std::fmt::Write as _;
10	use std::fs;
11	use std::hash::{BuildHasher, RandomState};
12	use std::path::{Path, PathBuf};
13	use std::process::Command;
14	use std::time::{SystemTime, UNIX_EPOCH};
15	
16	use anyhow::{Context as _, Result, anyhow};
17	use serde_json::Value;
18	
19	use crate::chat_input::SendMode;
20	use crate::project_directory::CONFIG_FILE_NAME;
21	
22	/// Indentation of each prompt line inside the anchor's `userPrompt` block.
23	pub const PROMPT_INDENT: &str = "        ";
24	
25	/// Where the application keeps its files, relative to the project directory.
26	pub const APP_DIR: &str = ".suspense";
27	const HISTORY_DIR: &str = "history";
28	
29	/// The hidden anchor's imports: names by module.
30	#[derive(Clone, Debug, Default)]
31	pub struct Imports(BTreeMap<String, BTreeSet<String>>);
32	
33	impl Imports {
34	    /// Adds the names of every `from <module> import A, B` line in `source`,
35	    /// ignoring other lines. Returns whether any name was new.
36	    pub fn add_from_source(&mut self, source: &str) -> bool {
37	        let mut added = false;
38	        for line in source.lines() {
39	            let Some((module, names)) = line
40	                .trim()
41	                .strip_prefix("from ")
42	                .and_then(|rest| rest.split_once(" import "))
43	            else {
44	                continue;
45	            };
46	            let names: Vec<&str> = names
47	                .split(',')
48	                .map(str::trim)
49	                .filter(|name| !name.is_empty())
50	                .collect();
51	            if names.is_empty() {
52	                continue;
53	            }
54	            let imported = self.0.entry(absolute_module(module.trim())).or_default();
55	            for name in names {
56	                added |= imported.insert(name.to_string());
57	            }
58	        }
59	        added
60	    }
61	
62	    /// Adds every name in `other`.
63	    pub fn extend(&mut self, other: &Imports) {
64	        for (module, names) in &other.0 {
65	            self.0
66	                .entry(module.clone())
67	                .or_default()
68	                .extend(names.iter().cloned());
69	        }
70	    }
71	}
72	
73	/// Relative imports come from a draft sitting at the spec root; the absolute
74	/// form resolves the same from anywhere in the project, history files included.
75	fn absolute_module(module: &str) -> String {
76	    match module.strip_prefix("./") {
77	        Some(path) => format!("/{path}"),
78	        None => module.to_string(),
79	    }
80	}
81	
82	pub struct HiddenAnchor {
83	    name: String,
84	    pub imports: Imports,
85	    /// The `systemPrompt` written after the `userPrompt`, if any.
86	    pub system_prompt: Option<String>,
87	}
88	
89	/// A compiled hidden anchor.
90	pub struct CompiledPrompt {
91	    pub user_prompt: String,
92	    pub system_prompt: Option<String>,
93	}
94	
95	impl HiddenAnchor {
96	    /// A freshly named anchor with no imports and no system prompt.
97	    pub fn random() -> Self {
98	        Self {
99	            name: format!(
100	                "Prompt_{:016x}",
101	                RandomState::new().hash_one(SystemTime::now())
102	            ),
103	            imports: Imports::default(),
104	            system_prompt: None,
105	        }
106	    }
107	
108	    pub fn name(&self) -> &str {
109	        &self.name
110	    }
111	
112	    /// The Piton source of this anchor with `prompt` as its `userPrompt`.
113	    pub fn source(&self, prompt: &str) -> String {
114	        let mut source = String::new();
115	        for (module, names) in &self.imports.0 {
116	            let names: Vec<&str> = names.iter().map(String::as_str).collect();
117	            writeln!(source, "from {module} import {}", names.join(", ")).ok();
118	        }
119	        writeln!(source, "\nanchor {}:\n    userPrompt:", self.name).ok();
120	        push_block(&mut source, prompt);
121	        // After the prompt, so the prompt's lines stay where
122	        // `prompt_first_line` says they are.
123	        if let Some(system_prompt) = &self.system_prompt {
124	            source.push('\n');
125	            source.push_str(SYSTEM_PROMPT_LINE);
126	            source.push('\n');
127	            push_block(&mut source, system_prompt);
128	        }
129	        source
130	    }
131	
132	    /// Reads back an anchor saved with [`Self::source`], with the prompt it
133	    /// holds.
134	    pub fn parse(source: &str) -> Option<(Self, String)> {
135	        let mut imports = Imports::default();
136	        let mut lines = source.lines();
137	        let name = loop {
138	            let line = lines.next()?;
139	            if let Some(name) = line
140	                .strip_prefix("anchor ")
141	                .and_then(|rest| rest.strip_suffix(':'))
142	            {
143	                break name.to_string();
144	            }
145	            imports.add_from_source(line);
146	        };
147	        if lines.next()?.trim() != "userPrompt:" {
148	            return None;
149	        }
150	        let lines: Vec<&str> = lines.collect();
151	        // Prompt lines are indented deeper, so only the property itself
152	        // matches this line.
153	        let (prompt, system_prompt) =
154	            match lines.iter().position(|line| *line == SYSTEM_PROMPT_LINE) {
155	                Some(at) => {
156	                    // Drop the blank line separating the two properties; prompt
157	                    // lines, even empty ones, are always indented.
158	                    let prompt = &lines[..at];
159	                    let prompt = prompt.strip_suffix(&[""]).unwrap_or(prompt);
160	                    (unindent(prompt), Some(unindent(&lines[at + 1..])))
161	                }
162	                None => (unindent(&lines), None),
163	            };
164	        Some((
165	            Self {
166	                name,
167	                imports,
168	                system_prompt,
169	            },
170	            prompt,
171	        ))
172	    }
173	
174	    /// The zero-based line of [`Self::source`] holding the prompt's first line.
175	    pub fn prompt_first_line(&self) -> u32 {
176	        self.imports.0.len() as u32 + 3
177	    }
178	}
179	
180	/// The line opening the `systemPrompt` property of [`HiddenAnchor::source`].
181	const SYSTEM_PROMPT_LINE: &str = "    systemPrompt:";
182	
183	/// The text of a property's indented lines, as written by [`push_block`].
184	fn unindent(block: &[&str]) -> String {
185	    block
186	        .iter()
187	        .map(|line| line.strip_prefix(PROMPT_INDENT).unwrap_or(line.trim()))
188	        .collect::<Vec<_>>()
189	        .join("\n")
190	}
191	
192	/// Adds `text` to `source` as the indented lines of a property.
193	fn push_block(source: &mut String, text: &str) {
194	    for line in text.split('\n') {
195	        source.push_str(PROMPT_INDENT);
196	        source.push_str(line.trim_end_matches('\r'));
197	        source.push('\n');
198	    }
199	}
200	
201	/// The system prompt a prompt sent in `mode` is given, naming the code and
202	/// spec locations set in the project's `piton.config.pi`.
203	pub fn system_prompt(mode: SendMode, project_dir: &Path) -> Result<String> {
204	    let code = config_value(project_dir, "codeRoot")?;
205	    let spec = config_value(project_dir, "root")?;
206	    Ok(match mode {
207	        SendMode::Code => format!(
208	            "We're working on the code located in {code}. Don't edit the spec located in {spec}."
209	        ),
210	        SendMode::Both => format!(
211	            "We're working on both the code located in {code} and the spec located in {spec}. Edit both of them."
212	        ),
213	        SendMode::Spec => format!(
214	            "We're working on the spec located in {spec}. Don't edit the code located in {code}."
215	        ),
216	    })
217	}
218	
219	/// The path the chat input's unsent text is presented to `piton lsp` under.
220	/// Nothing is written there. It sits inside the spec root because `piton lsp`
221	/// only resolves imports, and offers auto-imports, for documents under it.
222	pub fn draft_path(project_dir: &Path) -> PathBuf {
223	    let spec_root = spec_root(project_dir).unwrap_or_default();
224	    project_dir.join(spec_root).join(".suspense-draft.pi")
225	}
226	
227	/// The project's prompt history directory.
228	pub fn history_dir(project_dir: &Path) -> PathBuf {
229	    project_dir.join(APP_DIR).join(HISTORY_DIR)
230	}
231	
232	/// Saves `prompt`, as `anchor`'s source, to the project's prompt history.
233	pub fn save(anchor: &HiddenAnchor, prompt: &str, project_dir: &Path) -> Result<PathBuf> {
234	    let history_dir = history_dir(project_dir);
235	    fs::create_dir_all(&history_dir)
236	        .with_context(|| format!("could not create {}", history_dir.display()))?;
237	    let sent_at = SystemTime::now()
238	        .duration_since(UNIX_EPOCH)
239	        .map_or(0, |elapsed| elapsed.as_secs());
240	    let file = history_dir.join(format!("{sent_at}-{}.pi", anchor.name));
241	    fs::write(&file, anchor.source(prompt))
242	        .with_context(|| format!("could not save {}", file.display()))?;
243	    Ok(file)
244	}
245	
246	/// Compiles `file`, a saved `anchor`, and returns its compiled prompt text.
247	pub fn compile(anchor: &HiddenAnchor, file: &Path, project_dir: &Path) -> Result<CompiledPrompt> {
248	    let output = Command::new("piton")
249	        .args(["compile", "--stdout"])
250	        .arg(file)
251	        .current_dir(project_dir)
252	        .output()
253	        .context("could not run `piton compile`")?;
254	    if !output.status.success() {
255	        let mut message = String::from_utf8_lossy(&output.stdout).into_owned();
256	        message.push_str(&String::from_utf8_lossy(&output.stderr));
257	        return Err(anyhow!("{}", message.trim()));
258	    }
259	
260	    let compiled: Value =
261	        serde_json::from_slice(&output.stdout).context("`piton compile` did not print JSON")?;
262	    let compiled = compiled
263	        .get(&anchor.name)
264	        .ok_or_else(|| anyhow!("the compiled output has no {}", anchor.name))?;
265	    let user_prompt = compiled
266	        .get("userPrompt")
267	        .ok_or_else(|| anyhow!("the compiled anchor has no userPrompt"))?;
268	    Ok(CompiledPrompt {
269	        user_prompt: prose(user_prompt),
270	        system_prompt: compiled.get("systemPrompt").map(prose),
271	    })
272	}
273	
274	/// Reads the spec root (`root:`) from the project's `piton.config.pi`.
275	fn spec_root(project_dir: &Path) -> Result<PathBuf> {
276	    config_value(project_dir, "root").map(PathBuf::from)
277	}
278	
279	/// Reads the first `key:` value in the project's `piton.config.pi`.
280	pub fn config_value(project_dir: &Path, key: &str) -> Result<String> {
281	    let config_path = project_dir.join(CONFIG_FILE_NAME);
282	    let config = fs::read_to_string(&config_path)
283	        .with_context(|| format!("could not read {}", config_path.display()))?;
284	    config
285	        .lines()
286	        .find_map(|line| line.trim().strip_prefix(key)?.strip_prefix(':'))
287	        .map(|value| value.trim().to_string())
288	        .ok_or_else(|| anyhow!("{} has no {key}", config_path.display()))
289	}
290	
291	/// Turns a compiled `userPrompt` back into text: paragraphs are separated by
292	/// blank lines and lists become `- ` items.
293	fn prose(value: &Value) -> String {
294	    match value {
295	        Value::String(text) => text.clone(),
296	        Value::Array(blocks) => blocks
297	            .iter()
298	            .map(|block| match block {
299	                Value::Array(items) => items
300	                    .iter()
301	                    .map(|item| format!("- {}", prose(item)))
302	                    .collect::<Vec<_>>()
303	                    .join("\n"),
304	                other => prose(other),
305	            })
306	            .collect::<Vec<_>>()
307	            .join("\n\n"),
308	        Value::Null => String::new(),
309	        other => serde_json::to_string_pretty(other).unwrap_or_default(),
310	    }
311	}
312	
313	#[cfg(test)]
314	mod tests {
315	    use std::fs;
316	    use std::path::Path;
317	
318	    use super::{
319	        HiddenAnchor, Imports, PROMPT_INDENT, SYSTEM_PROMPT_LINE, compile, prose, system_prompt,
320	    };
321	    use crate::chat_input::SendMode;
