/// How strongly the selected tabs and their body are tinted: red for Code,
/// blue for Spec, and purple for both.
const TINT_OPACITY: f32 = 0.1;

/// The tint at `position` between the tabs: red at Code (0), blue at Spec
/// (2), and purple for both (1), where they meet.
fn tint(red: Hsla, blue: Hsla, position: f32) -> Hsla {
    let t = (position / 2.).clamp(0., 1.);
    // The shorter way round the hue circle, which from red to blue passes
    // through purple rather than green.
    let hue_step = (blue.h - red.h + 0.5).rem_euclid(1.) - 0.5;
    Hsla {
        h: (red.h + hue_step * t).rem_euclid(1.),
        s: red.s + (blue.s - red.s) * t,
        l: red.l + (blue.l - red.l) * t,
        a: TINT_OPACITY,
    }
}

